test_that("biomechanics/tests/test_activation.py::TestFirstOrderActivationDeGroote2016::test_F matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("pysetattr(self, \"name\", \"name\")", e)
  .run("pysetattr(self, \"e\", dynamicsymbols(\"e_name\"))", e)
  .run("pysetattr(self, \"a\", dynamicsymbols(\"a_name\"))", e)
  .run("pysetattr(self, \"tau_a\", Symbol(\"tau_a\"))", e)
  .run("pysetattr(self, \"tau_d\", Symbol(\"tau_d\"))", e)
  .run("pysetattr(self, \"b\", Symbol(\"b\"))", e)
  .run("pysetattr(self, \"instance\", FirstOrderActivationDeGroote2016(pyattr(self, \"name\"), pyattr(self, \"tau_a\"), pyattr(self, \"tau_d\"), pyattr(self, \"b\")))", e)
  expect_equal(.case("pyhasattr(pyattr(self, \"instance\"), \"F\")", e), "True")
  .run("da_expr <- ((((1 / (pyattr(self, \"tau_a\") * (Rational(1, 2) + (Rational(3, 2) * pyattr(self, \"a\"))))) * (Rational(1, 2) + (Rational(1, 2) * tanh((pyattr(self, \"b\") * (pyattr(self, \"e\") - pyattr(self, \"a\"))))))) + (((Rational(1, 2) + (Rational(3, 2) * pyattr(self, \"a\"))) / pyattr(self, \"tau_d\")) * (Rational(1, 2) - (Rational(1, 2) * tanh((pyattr(self, \"b\") * (pyattr(self, \"e\") - pyattr(self, \"a\")))))))) * (pyattr(self, \"e\") - pyattr(self, \"a\")))", e)
  .run("F_expected <- Matrix(list(da_expr))", e)
  expect_equal(.case("pyattr(pyattr(self, \"instance\"), \"F\")", e), "Matrix([[((1/2 - tanh(b*(-a_name(t) + e_name(t)))/2)*(3*a_name(t)/2 + 1/2)/tau_d + (tanh(b*(-a_name(t) + e_name(t)))/2 + 1/2)/(tau_a*(3*a_name(t)/2 + 1/2)))*(-a_name(t) + e_name(t))]])")
  expect_equal(.case("pyisinstance(pyattr(pyattr(self, \"instance\"), \"F\"), Matrix)", e), "True")
  expect_equal(.case("pyattr(pyattr(pyattr(self, \"instance\"), \"F\"), \"shape\")", e), "(1, 1)")
})

