  .run("l_M <- (pyattr(self, \"l_M_tilde\") * pyattr(self, \"l_M_opt\"))", e)
  .run("l_T <- (l_MT - sqrt((pypow(l_M, 2) - pypow((pyattr(self, \"l_M_opt\") * sin(pyattr(self, \"alpha_opt\"))), 2))))", e)
  .run("fl_T <- pycall(pyattr(curve, \"tendon_force_length\"), \"with_defaults\", (l_T / pyattr(self, \"l_T_slack\")))", e)
  .run("fl_M_pas <- pycall(pyattr(curve, \"fiber_force_length_passive\"), \"with_defaults\", pyattr(self, \"l_M_tilde\"))", e)
  .run("fl_M_act <- pycall(pyattr(curve, \"fiber_force_length_active\"), \"with_defaults\", pyattr(self, \"l_M_tilde\"))", e)
  .run("v_M_tilde <- pycall(pyattr(curve, \"fiber_force_velocity_inverse\"), \"with_defaults\", (((((fl_T * pyattr(self, \"F_M_max\")) / ((l_MT - l_T) / l_M)) / pyattr(self, \"F_M_max\")) - fl_M_pas) / (pyattr(self, \"a\") * fl_M_act)))", e)
  .run("pysetattr(self, \"dl_M_tilde_expr\", ((pyattr(self, \"v_M_max\") / pyattr(self, \"l_M_opt\")) * v_M_tilde))", e)
  .run("pysetattr(self, \"da_expr\", ((((1 / (pyattr(self, \"tau_a\") * (Rational(1, 2) + (Rational(3, 2) * pyattr(self, \"a\"))))) * (Rational(1, 2) + (Rational(1, 2) * tanh((pyattr(self, \"b\") * (pyattr(self, \"e\") - pyattr(self, \"a\"))))))) + (((Rational(1, 2) + (Rational(3, 2) * pyattr(self, \"a\"))) / pyattr(self, \"tau_d\")) * (Rational(1, 2) - (Rational(1, 2) * tanh((pyattr(self, \"b\") * (pyattr(self, \"e\") - pyattr(self, \"a\")))))))) * (pyattr(self, \"e\") - pyattr(self, \"a\"))))", e)
  expect_equal(.case("pyhasattr(pyattr(self, \"instance\"), \"F\")", e), "True")
  .run("F_expected <- Matrix(list(pyattr(self, \"dl_M_tilde_expr\"), pyattr(self, \"da_expr\")))", e)
  expect_equal(.case("pyattr(pyattr(self, \"instance\"), \"F\")", e), "Matrix([[v_M_max*FiberForceVelocityInverseDeGroote2016((l_M_opt*l_M_tilde_name(t)*TendonForceLengthDeGroote2016((-sqrt(l_M_opt^2*l_M_tilde_name(t)^2 - l_M_opt^2*sin(alpha_opt)^2) + sqrt(q(t)^2))/l_T_slack, 0.2, 0.995, 0.25, 33.93669377311689)/sqrt(l_M_opt^2*l_M_tilde_name(t)^2 - l_M_opt^2*sin(alpha_opt)^2) - FiberForceLengthPassiveDeGroote2016(l_M_tilde_name(t), 0.6, 4.0))/(a_name(t)*FiberForceLengthActiveDeGroote2016(l_M_tilde_name(t), 0.814, 1.06, 0.162, 0.0633, 0.433, 0.717, -0.0299, 0.2, 0.1, 1.0, 0.354, 0.0)), -0.318, -8.149, -0.374, 0.886)/l_M_opt], [((1/2 - tanh(b_name*(-a_name(t) + e_name(t)))/2)*(3*a_name(t)/2 + 1/2)/tau_d_name + (tanh(b_name*(-a_name(t) + e_name(t)))/2 + 1/2)/(tau_a_name*(3*a_name(t)/2 + 1/2)))*(-a_name(t) + e_name(t))]])")
  expect_equal(.case("pyisinstance(pyattr(pyattr(self, \"instance\"), \"F\"), Matrix)", e), "True")
  expect_equal(.case("pyattr(pyattr(pyattr(self, \"instance\"), \"F\"), \"shape\")", e), "(2, 1)")
})

