  .run("v_T_tilde <- (v_T / pyattr(self, \"l_T_slack\"))", e)
  .run("pysetattr(self, \"dF_T_tilde_expr\", (((Float(\"0.2\") * Float(\"33.93669377311689\")) * exp((Float(\"33.93669377311689\") * UnevaluatedExpr((l_T_tilde - Float(\"0.995\")))))) * v_T_tilde))", e)
  .run("pysetattr(self, \"da_expr\", ((((1 / (pyattr(self, \"tau_a\") * (Rational(1, 2) + (Rational(3, 2) * pyattr(self, \"a\"))))) * (Rational(1, 2) + (Rational(1, 2) * tanh((pyattr(self, \"b\") * (pyattr(self, \"e\") - pyattr(self, \"a\"))))))) + (((Rational(1, 2) + (Rational(3, 2) * pyattr(self, \"a\"))) / pyattr(self, \"tau_d\")) * (Rational(1, 2) - (Rational(1, 2) * tanh((pyattr(self, \"b\") * (pyattr(self, \"e\") - pyattr(self, \"a\")))))))) * (pyattr(self, \"e\") - pyattr(self, \"a\"))))", e)
  expect_equal(.case("pyhasattr(pyattr(self, \"instance\"), \"x\")", e), "True")
  expect_equal(.case("pyhasattr(pyattr(self, \"instance\"), \"state_vars\")", e), "True")
  expect_equal(.case("pyattr(pyattr(self, \"instance\"), \"x\")", e), "Matrix([[F_T_tilde_name(t)], [a_name(t)]])")
  .run("x_expected <- Matrix(list(pyattr(self, \"F_T_tilde\"), pyattr(self, \"a\")))", e)
  expect_equal(.case("pyattr(pyattr(self, \"instance\"), \"x\")", e), "Matrix([[F_T_tilde_name(t)], [a_name(t)]])")
  expect_equal(.case("pyattr(pyattr(self, \"instance\"), \"state_vars\")", e), "Matrix([[F_T_tilde_name(t)], [a_name(t)]])")
  expect_equal(.case("pyisinstance(pyattr(pyattr(self, \"instance\"), \"x\"), Matrix)", e), "True")
  expect_equal(.case("pyisinstance(pyattr(pyattr(self, \"instance\"), \"state_vars\"), Matrix)", e), "True")
  expect_equal(.case("pyattr(pyattr(pyattr(self, \"instance\"), \"x\"), \"shape\")", e), "(2, 1)")
  expect_equal(.case("pyattr(pyattr(pyattr(self, \"instance\"), \"state_vars\"), \"shape\")", e), "(2, 1)")
})

