test_that("biomechanics/tests/test_musculotendon.py::TestTendonForceExplicit::test_constants matches SymPy", {
  e <- new.env(parent = .menv)
  .wstate$mode <- "default"
  .run("self <- pyself()", e)
  .run("musculotendon_concrete <- MusculotendonDeGroote2016", e)
  .run("curve <- CharacteristicCurveCollection(tendon_force_length = TendonForceLengthDeGroote2016, tendon_force_length_inverse = TendonForceLengthInverseDeGroote2016, fiber_force_length_passive = FiberForceLengthPassiveDeGroote2016, fiber_force_length_passive_inverse = FiberForceLengthPassiveInverseDeGroote2016, fiber_force_length_active = FiberForceLengthActiveDeGroote2016, fiber_force_velocity = FiberForceVelocityDeGroote2016, fiber_force_velocity_inverse = FiberForceVelocityInverseDeGroote2016)", e)
  .run("pysetattr(self, \"name\", \"name\")", e)
  .run("pysetattr(self, \"N\", ReferenceFrame(\"N\"))", e)
  .run("pysetattr(self, \"q\", dynamicsymbols(\"q\"))", e)
  .run("pysetattr(self, \"origin\", PhysPoint(\"pO\"))", e)
  .run("pysetattr(self, \"insertion\", PhysPoint(\"pI\"))", e)
  .run("pycall(pyattr(self, \"insertion\"), \"set_pos\", pyattr(self, \"origin\"), (pyattr(self, \"q\") * pyattr(pyattr(self, \"N\"), \"x\")))", e)
  .run("pysetattr(self, \"pathway\", LinearPathway(pyattr(self, \"origin\"), pyattr(self, \"insertion\")))", e)
  .run("pysetattr(self, \"activation\", FirstOrderActivationDeGroote2016(pyattr(self, \"name\")))", e)
  .run("pysetattr(self, \"e\", pyattr(pyattr(self, \"activation\"), \"excitation\"))", e)
  .run("pysetattr(self, \"a\", pyattr(pyattr(self, \"activation\"), \"activation\"))", e)
  .run("pysetattr(self, \"tau_a\", pyattr(pyattr(self, \"activation\"), \"activation_time_constant\"))", e)
  .run("pysetattr(self, \"tau_d\", pyattr(pyattr(self, \"activation\"), \"deactivation_time_constant\"))", e)
  .run("pysetattr(self, \"b\", pyattr(pyattr(self, \"activation\"), \"smoothing_rate\"))", e)
  .run("pysetattr(self, \"formulation\", pyclassmethod(\"MusculotendonFormulation\", \"TENDON_FORCE_EXPLICIT\"))", e)
  .run("pysetattr(self, \"l_T_slack\", Symbol(\"l_T_slack\"))", e)
  .run("pysetattr(self, \"F_M_max\", Symbol(\"F_M_max\"))", e)
  .run("pysetattr(self, \"l_M_opt\", Symbol(\"l_M_opt\"))", e)
  .run("pysetattr(self, \"v_M_max\", Symbol(\"v_M_max\"))", e)
  .run("pysetattr(self, \"alpha_opt\", Symbol(\"alpha_opt\"))", e)
  .run("pysetattr(self, \"beta\", Symbol(\"beta\"))", e)
  .run("pysetattr(self, \"instance\", musculotendon_concrete(pyattr(self, \"name\"), pyattr(self, \"pathway\"), pyattr(self, \"activation\"), musculotendon_dynamics = pyattr(self, \"formulation\"), tendon_slack_length = pyattr(self, \"l_T_slack\"), peak_isometric_force = pyattr(self, \"F_M_max\"), optimal_fiber_length = pyattr(self, \"l_M_opt\"), maximal_fiber_velocity = pyattr(self, \"v_M_max\"), optimal_pennation_angle = pyattr(self, \"alpha_opt\"), fiber_damping_coefficient = pyattr(self, \"beta\"), with_defaults = TRUE))", e)
  .run("pysetattr(self, \"F_T_tilde\", dynamicsymbols(\"F_T_tilde_name\"))", e)
  .run("l_T_tilde <- pycall(pyattr(curve, \"tendon_force_length_inverse\"), \"with_defaults\", pyattr(self, \"F_T_tilde\"))", e)
  .run("l_MT <- pyattr(pyattr(self, \"pathway\"), \"length\")", e)
  .run("v_MT <- pyattr(pyattr(self, \"pathway\"), \"extension_velocity\")", e)
  .run("l_T <- (l_T_tilde * pyattr(self, \"l_T_slack\"))", e)
  .run("l_M <- sqrt((pypow((l_MT - l_T), 2) + pypow((pyattr(self, \"l_M_opt\") * sin(pyattr(self, \"alpha_opt\"))), 2)))", e)
  .run("l_M_tilde <- (l_M / pyattr(self, \"l_M_opt\"))", e)
  .run("cos_alpha <- ((l_MT - l_T) / l_M)", e)
  .run("F_T <- (pyattr(self, \"F_T_tilde\") * pyattr(self, \"F_M_max\"))", e)
  .run("F_M <- (F_T / cos_alpha)", e)
  .run("F_M_tilde <- (F_M / pyattr(self, \"F_M_max\"))", e)
  .run("fl_M_pas <- pycall(pyattr(curve, \"fiber_force_length_passive\"), \"with_defaults\", l_M_tilde)", e)
  .run("fl_M_act <- pycall(pyattr(curve, \"fiber_force_length_active\"), \"with_defaults\", l_M_tilde)", e)
  .run("fv_M <- ((F_M_tilde - fl_M_pas) / (pyattr(self, \"a\") * fl_M_act))", e)
  .run("v_M_tilde <- pycall(pyattr(curve, \"fiber_force_velocity_inverse\"), \"with_defaults\", fv_M)", e)
  .run("v_M <- (v_M_tilde * pyattr(self, \"v_M_max\"))", e)
  .run("v_T <- (v_MT - (v_M / cos_alpha))", e)
  .run("v_T_tilde <- (v_T / pyattr(self, \"l_T_slack\"))", e)
  .run("pysetattr(self, \"dF_T_tilde_expr\", (((Float(\"0.2\") * Float(\"33.93669377311689\")) * exp((Float(\"33.93669377311689\") * UnevaluatedExpr((l_T_tilde - Float(\"0.995\")))))) * v_T_tilde))", e)
  .run("pysetattr(self, \"da_expr\", ((((1 / (pyattr(self, \"tau_a\") * (Rational(1, 2) + (Rational(3, 2) * pyattr(self, \"a\"))))) * (Rational(1, 2) + (Rational(1, 2) * tanh((pyattr(self, \"b\") * (pyattr(self, \"e\") - pyattr(self, \"a\"))))))) + (((Rational(1, 2) + (Rational(3, 2) * pyattr(self, \"a\"))) / pyattr(self, \"tau_d\")) * (Rational(1, 2) - (Rational(1, 2) * tanh((pyattr(self, \"b\") * (pyattr(self, \"e\") - pyattr(self, \"a\")))))))) * (pyattr(self, \"e\") - pyattr(self, \"a\"))))", e)
  expect_equal(.case("pyhasattr(pyattr(self, \"instance\"), \"p\")", e), "True")
  expect_equal(.case("pyhasattr(pyattr(self, \"instance\"), \"constants\")", e), "True")
  expect_equal(.case("pyattr(pyattr(self, \"instance\"), \"p\")", e), "Matrix([[l_T_slack], [F_M_max], [l_M_opt], [v_M_max], [alpha_opt], [beta], [tau_a_name], [tau_d_name], [b_name]])")
  .run("p_expected <- Matrix(list(pyattr(self, \"l_T_slack\"), pyattr(self, \"F_M_max\"), pyattr(self, \"l_M_opt\"), pyattr(self, \"v_M_max\"), pyattr(self, \"alpha_opt\"), pyattr(self, \"beta\"), pyattr(self, \"tau_a\"), pyattr(self, \"tau_d\"), pyattr(self, \"b\")))", e)
  expect_equal(.case("pyattr(pyattr(self, \"instance\"), \"p\")", e), "Matrix([[l_T_slack], [F_M_max], [l_M_opt], [v_M_max], [alpha_opt], [beta], [tau_a_name], [tau_d_name], [b_name]])")
  expect_equal(.case("pyattr(pyattr(self, \"instance\"), \"constants\")", e), "Matrix([[l_T_slack], [F_M_max], [l_M_opt], [v_M_max], [alpha_opt], [beta], [tau_a_name], [tau_d_name], [b_name]])")
  expect_equal(.case("pyisinstance(pyattr(pyattr(self, \"instance\"), \"p\"), Matrix)", e), "True")
  expect_equal(.case("pyisinstance(pyattr(pyattr(self, \"instance\"), \"constants\"), Matrix)", e), "True")
  expect_equal(.case("pyattr(pyattr(pyattr(self, \"instance\"), \"p\"), \"shape\")", e), "(9, 1)")
  expect_equal(.case("pyattr(pyattr(pyattr(self, \"instance\"), \"constants\"), \"shape\")", e), "(9, 1)")
})

